import { threadKey } from './open-thread.js';
export const DOCUMENT_THREADS_KEY = 'p1-document-threads';
export const NO_THREADS = Object.freeze({});
const PAGE_SIZE = 500;
export function documentThreadsKey(siteId, documentId) {
    return [DOCUMENT_THREADS_KEY, siteId, documentId];
}
export function overviewKey(thread) {
    return threadKey(thread.context.type, thread.context.id);
}
export function indexThreads(threads) {
    const byContext = {};
    for (const thread of threads) {
        byContext[overviewKey(thread)] = thread;
    }
    return byContext;
}
export async function fetchDocumentThreads(client, siteId, documentId) {
    const threads = [];
    let cursor;
    do {
        const page = await client.threads.listThreads(siteId, {
            documentId,
            limit: PAGE_SIZE,
            cursor,
        });
        threads.push(...page.threads);
        cursor = page.nextCursor ?? undefined;
    } while (cursor !== undefined);
    return indexThreads(threads);
}
