import { isComponentNode, isUnsafeKey, stripTrailingSlash } from "./paths";
export const CROSS_PAGE_REF_REGEX = /\{\{\s*pages\[("[^"\\]*(?:\\.[^"\\]*)*")\]\.blocks\[("[^"\\]*(?:\\.[^"\\]*)*")\]\.props\.([\w.]+)\s*\}\}/g;
const CONNECTABLE_FIELD_TYPES = new Set([
    "text",
    "textarea",
    "number",
    "select",
    "radio",
]);
export const MAX_XREF_DEPTH = 10;
function findPropsByIdInNodes(nodes, id) {
    if (!Array.isArray(nodes))
        return null;
    for (const item of nodes) {
        if (!isComponentNode(item))
            continue;
        const props = item.props;
        if (props.id === id)
            return props;
        for (const val of Object.values(props)) {
            if (Array.isArray(val)) {
                const found = findPropsByIdInNodes(val, id);
                if (found)
                    return found;
            }
        }
    }
    return null;
}
export function getBlockPropsById(data, componentId) {
    if (componentId === "root" || componentId === "puck-root") {
        const root = data.root;
        if (!root)
            return null;
        const nested = root.props;
        if (nested)
            return { ...nested };
        return { ...root };
    }
    const fromContent = findPropsByIdInNodes(data.content, componentId);
    if (fromContent)
        return { ...fromContent };
    const zones = data.zones;
    if (zones && typeof zones === "object") {
        for (const z of Object.values(zones)) {
            const fz = findPropsByIdInNodes(z, componentId);
            if (fz)
                return { ...fz };
        }
    }
    return null;
}
function getPropFromObject(obj, propPath) {
    const parts = propPath.split(".");
    let cur = obj;
    for (const p of parts) {
        if (isUnsafeKey(p))
            return undefined;
        if (cur == null || typeof cur !== "object" || Array.isArray(cur)) {
            return undefined;
        }
        cur = cur[p];
    }
    return cur;
}
export function getRawPropValue(data, componentId, propPath) {
    if (componentId === "root") {
        const root = data.root;
        if (!root)
            return undefined;
        const nested = root.props;
        if (nested) {
            const v = getPropFromObject(nested, propPath);
            if (v !== undefined)
                return v;
        }
        return getPropFromObject(root, propPath);
    }
    const fromContent = findPropsByIdInNodes(data.content, componentId);
    if (fromContent) {
        const v = getPropFromObject(fromContent, propPath);
        if (v !== undefined)
            return v;
    }
    const zones = data.zones;
    if (zones && typeof zones === "object") {
        for (const z of Object.values(zones)) {
            const fromZ = findPropsByIdInNodes(z, componentId);
            if (fromZ) {
                const v = getPropFromObject(fromZ, propPath);
                if (v !== undefined)
                    return v;
            }
        }
    }
    return undefined;
}
export function normalizeRoutePathForRef(p) {
    return stripTrailingSlash(p);
}
export function encodePagesBlocksTemplate(path, blockId, propKey) {
    const p = normalizeRoutePathForRef(path);
    return `{{ pages[${JSON.stringify(p)}].blocks[${JSON.stringify(blockId)}].props.${propKey} }}`;
}
export function isPagesBlocksTemplateString(value) {
    if (typeof value !== "string")
        return false;
    return value.search(CROSS_PAGE_REF_REGEX) !== -1;
}
export function isCrossPageRefTemplateString(value) {
    return isPagesBlocksTemplateString(value);
}
function walkNodes(nodes, config, out) {
    if (!Array.isArray(nodes))
        return;
    for (const item of nodes) {
        if (!isComponentNode(item))
            continue;
        const { type, props } = item;
        const id = typeof props.id === "string" ? props.id : "?";
        const compConf = config.components[type];
        const labelBase = compConf?.label ?? type;
        out.push({
            id,
            type,
            label: `${labelBase} · ${id.length > 14 ? `${id.slice(0, 12)}…` : id}`,
        });
        for (const val of Object.values(props)) {
            if (Array.isArray(val))
                walkNodes(val, config, out);
        }
    }
}
export function flattenComponents(data, config) {
    const out = [{ id: "root", type: "root", label: "Page root" }];
    walkNodes(data.content, config, out);
    const zones = data.zones;
    if (zones && typeof zones === "object") {
        for (const z of Object.values(zones)) {
            walkNodes(z, config, out);
        }
    }
    const seen = new Set();
    return out.filter((c) => {
        if (seen.has(c.id))
            return false;
        seen.add(c.id);
        return true;
    });
}
export function listConnectablePropKeys(config, componentType) {
    if (componentType === "root") {
        const fields = config.root?.fields;
        if (!fields)
            return [];
        return Object.entries(fields)
            .filter(([, f]) => {
            const t = f?.type;
            return typeof t === "string" && CONNECTABLE_FIELD_TYPES.has(t);
        })
            .map(([k]) => k);
    }
    const comp = config.components[componentType];
    if (!comp?.fields)
        return [];
    return Object.entries(comp.fields)
        .filter(([, f]) => {
        const t = f?.type;
        return typeof t === "string" && CONNECTABLE_FIELD_TYPES.has(t);
    })
        .map(([k]) => k);
}
