const LEGACY_LS_PREFIX = 'p1-thumb:';
const memory = new Map();
function hashString(input) {
    let hash = 5381;
    for (let i = 0; i < input.length; i++) {
        hash = ((hash << 5) + hash + input.charCodeAt(i)) | 0;
    }
    return (hash >>> 0).toString(36);
}
function getStore() {
    try {
        return typeof globalThis !== 'undefined' && globalThis.localStorage
            ? globalThis.localStorage
            : null;
    }
    catch {
        return null;
    }
}
export function makeThumbnailKey(name, defaultProps, version = '2') {
    let serialized = '';
    try {
        serialized = JSON.stringify(defaultProps) ?? '';
    }
    catch {
        serialized = '';
    }
    return `${name}:${hashString(`${version}|${serialized}`)}`;
}
function defaultPropsFor(config, name) {
    return config?.components?.[name]?.defaultProps ?? {};
}
export function getThumbnailCacheKey(config, name, version) {
    return makeThumbnailKey(name, defaultPropsFor(config, name), version);
}
export function getCachedThumbnail(key) {
    return memory.get(key);
}
export function setCachedThumbnail(key, html) {
    memory.set(key, html);
}
export function clearThumbnailCache() {
    memory.clear();
    const store = getStore();
    if (store) {
        try {
            const keys = [];
            for (let i = 0; i < store.length; i++) {
                const k = store.key(i);
                if (k && k.startsWith(LEGACY_LS_PREFIX))
                    keys.push(k);
            }
            keys.forEach((k) => store.removeItem(k));
        }
        catch {
        }
    }
}
