const listeners = new Set();
let openThreadKey = null;
export function threadKey(contextType, contextId) {
    return `${contextType}:${contextId}`;
}
export function subscribeToOpenThread(onChange) {
    listeners.add(onChange);
    return () => {
        listeners.delete(onChange);
    };
}
export function getOpenThread() {
    return openThreadKey;
}
export function setOpenThread(key) {
    if (key === openThreadKey)
        return;
    openThreadKey = key;
    listeners.forEach((onChange) => onChange());
}
