import { useCallback, useContext, useEffect, useMemo, useSyncExternalStore } from 'react';
import { useP1PuckOptional } from '../../core/P1PuckContext.js';
import { P1SdkQueryClientContext } from '../../data/query-provider.js';
import { useThreadsEnabled } from './enabled.js';
import { mentionCandidates } from './mentions.js';
import { subscribeToQueryCache } from './query-cache.js';
export const SITE_MEMBERS_KEY = 'p1-site-members';
const NO_CANDIDATES = Object.freeze([]);
const FRESH_FOR_MS = 5 * 60_000;
const noop = () => { };
export function siteMembersKey(siteId) {
    return [SITE_MEMBERS_KEY, siteId];
}
export function useSiteMembers(wanted) {
    const ccr = useP1PuckOptional();
    const queryClient = useContext(P1SdkQueryClientContext);
    const enabled = useThreadsEnabled();
    const client = ccr?.client;
    const siteId = ccr?.siteId;
    const ready = enabled && wanted && Boolean(client && siteId && queryClient);
    const fetchRoster = useCallback(() => {
        if (!queryClient || !client || !siteId)
            return;
        void queryClient.prefetchQuery({
            queryKey: siteMembersKey(siteId),
            queryFn: () => client.sites.members(siteId),
            staleTime: FRESH_FOR_MS,
        });
    }, [queryClient, client, siteId]);
    useEffect(() => {
        if (ready)
            fetchRoster();
    }, [ready, fetchRoster]);
    const subscribe = useCallback((onChange) => (queryClient ? subscribeToQueryCache(queryClient, onChange) : noop), [queryClient]);
    const read = useCallback(() => queryClient?.getQueryCache().find({ queryKey: siteMembersKey(siteId) })?.state, [queryClient, siteId]);
    const state = useSyncExternalStore(subscribe, read, read);
    const roster = state?.data;
    const gone = state === undefined;
    useEffect(() => {
        if (ready && gone)
            fetchRoster();
    }, [ready, gone, fetchRoster]);
    const candidates = useMemo(() => (roster ? mentionCandidates(roster) : NO_CANDIDATES), [roster]);
    if (!ready)
        return { candidates: NO_CANDIDATES, loading: false };
    return { candidates, loading: roster === undefined && state?.status !== 'error' };
}
